require_once __DIR__.'/includes/functions.php';require_login();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=$_POST['type']??'';$dept=(int)($_POST['department_id']??0);$course=(int)($_POST['course_id']??0);$semester=(int)($_POST['semester_id']??0);$subject=(int)($_POST['subject_id']??0);$module=(int)($_POST['module_id']??0);$year=(int)($_POST['exam_year']??0);$exam=$_POST['exam_type']??null;
 $allowed=['question_paper','syllabus','notes','assignment','presentation','other'];
 if($title===''||!in_array($type,$allowed,true)||empty($_FILES['document']['name']))$errors[]='Title, resource type and document are required.';
 elseif($_FILES['document']['error']!==UPLOAD_ERR_OK)$errors[]='File upload failed.';
 elseif($_FILES['document']['size']>MAX_UPLOAD_BYTES)$errors[]='Maximum file size is 20 MB.';
 else{$tmp=$_FILES['document']['tmp_name'];$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($tmp);$ext=strtolower(pathinfo($_FILES['document']['name'],PATHINFO_EXTENSION));$valid=['pdf'=>'application/pdf','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document','ppt'=>'application/vnd.ms-powerpoint','pptx'=>'application/vnd.openxmlformats-officedocument.presentationml.presentation'];
 if(!isset($valid[$ext])||$valid[$ext]!==$mime)$errors[]='Allowed formats: PDF, DOC, DOCX, PPT and PPTX.';
 else{if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true);$stored=bin2hex(random_bytes(18)).'.'.$ext;$dest=UPLOAD_DIR.'/'.$stored;if(move_uploaded_file($tmp,$dest)){try{$s=$pdo->prepare("INSERT INTO resources(title,description,type,department_id,course_id,semester_id,subject_id,module_id,exam_year,exam_type,original_name,stored_name,mime_type,file_size,uploaded_by,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending')");$s->execute([$title,$desc,$type,$dept?:null,$course?:null,$semester?:null,$subject?:null,$module?:null,$year?:null,$exam?:null,basename($_FILES['document']['name']),$stored,$mime,(int)$_FILES['document']['size'],$u=current_user()['id']]);$id=(int)$pdo->lastInsertId();log_activity($pdo,current_user()['id'],'upload',$id);flash('success','Upload received. It will appear in the public library after administrator approval.');redirect('dashboard.php');}catch(Throwable $e){@unlink($dest);$errors[]='Could not save resource details. Check database setup.';}}else $errors[]='Could not store uploaded file.';}}
}
$departments=$pdo->query("SELECT id,name FROM departments ORDER BY name")->fetchAll();$courses=$pdo->query("SELECT id,name,department_id FROM courses ORDER BY name")->fetchAll();$semesters=$pdo->query("SELECT id,name FROM semesters ORDER BY id")->fetchAll();$subjects=$pdo->query("SELECT id,name,code,course_id,semester_id FROM subjects ORDER BY code")->fetchAll();$modules=$pdo->query("SELECT id,title,subject_id FROM modules ORDER BY module_no")->fetchAll();$page_title='Contribute a resource';require __DIR__.'/includes/header.php';?>
