 ?>"><?= e($m['title']) ?></option><?php endforeach; ?></select></label><label>Examination year (question papers)<input type="number" name="exam_year" min="2000" max="<?= date('Y')+1 ?>" placeholder="<?= date('Y') ?>"></label><label>Examination type<select name="exam_type"><option value="">Not applicable</option><option>Internal</option><option>End Semester</option><option>Supplementary</option><option>Model</option></select></label></div><label>Description<textarea name="description" rows="4" placeholder="Briefly describe this resource..."></textarea></label><label class="file-drop">Choose document (PDF, DOC, DOCX, PPT, PPTX · max 20 MB)<input type="file" name="document" accept=".pdf,.doc,.docx,.ppt,.pptx" required></label><button class="btn primary">Submit for approval</button></form>
